11	/* ----------------------------------------------------------------------------
12	We use our own PRNG to keep predictable performance of random number generation
13	and to avoid implementations that use a lock. We only use the OS provided
14	random source to initialize the initial seeds. Since we do not need ultimate
15	performance but we do rely on the security (for secret cookies in secure mode)
16	we use a cryptographically secure generator (chacha20).
17	-----------------------------------------------------------------------------*/
18	
19	#define MI_CHACHA_ROUNDS (20)   // perhaps use 12 for better performance?
20	
21	
22	/* ----------------------------------------------------------------------------
23	Chacha20 implementation as the original algorithm with a 64-bit nonce
24	and counter: https://en.wikipedia.org/wiki/Salsa20
25	The input matrix has sixteen 32-bit values:
26	Position  0 to  3: constant key
27	Position  4 to 11: the key
28	Position 12 to 13: the counter.
29	Position 14 to 15: the nonce.
30	
31	The implementation uses regular C code which compiles very well on modern compilers.
32	(gcc x64 has no register spills, and clang 6+ uses SSE instructions)
33	-----------------------------------------------------------------------------*/
34	
35	static inline void qround(uint32_t x[16], size_t a, size_t b, size_t c, size_t d) {
36	  x[a] += x[b]; x[d] = mi_rotl32(x[d] ^ x[a], 16);
37	  x[c] += x[d]; x[b] = mi_rotl32(x[b] ^ x[c], 12);
38	  x[a] += x[b]; x[d] = mi_rotl32(x[d] ^ x[a], 8);
39	  x[c] += x[d]; x[b] = mi_rotl32(x[b] ^ x[c], 7);
40	}
41	
42	static void chacha_block(mi_random_ctx_t* ctx)
43	{
44	  // scramble into `x`
45	  uint32_t x[16];
46	  for (size_t i = 0; i < 16; i++) {
47	    x[i] = ctx->input[i];
48	  }
49	  for (size_t i = 0; i < MI_CHACHA_ROUNDS; i += 2) {
50	    qround(x, 0, 4,  8, 12);
51	    qround(x, 1, 5,  9, 13);
52	    qround(x, 2, 6, 10, 14);
53	    qround(x, 3, 7, 11, 15);
54	    qround(x, 0, 5, 10, 15);
55	    qround(x, 1, 6, 11, 12);
56	    qround(x, 2, 7,  8, 13);
57	    qround(x, 3, 4,  9, 14);
58	  }
59	
60	  // add scrambled data to the initial state
61	  for (size_t i = 0; i < 16; i++) {
62	    ctx->output[i] = x[i] + ctx->input[i];
63	  }
64	  ctx->output_available = 16;
65	
66	  // increment the counter for the next round
67	  ctx->input[12] += 1;
68	  if (ctx->input[12] == 0) {
69	    ctx->input[13] += 1;
70	    if (ctx->input[13] == 0) {  // and keep increasing into the nonce
71	      ctx->input[14] += 1;
72	    }
73	  }
74	}
75	
76	static uint32_t chacha_next32(mi_random_ctx_t* ctx) {
77	  if (ctx->output_available <= 0) {
78	    chacha_block(ctx);
79	    ctx->output_available = 16; // (assign again to suppress static analysis warning)
80	  }
81	  const uint32_t x = ctx->output[16 - ctx->output_available];
82	  ctx->output[16 - ctx->output_available] = 0; // reset once the data is handed out
83	  ctx->output_available--;
84	  return x;
85	}
86	
87	static inline uint32_t read32(const uint8_t* p, size_t idx32) {
88	  const size_t i = 4*idx32;
89	  return ((uint32_t)p[i+0] | (uint32_t)p[i+1] << 8 | (uint32_t)p[i+2] << 16 | (uint32_t)p[i+3] << 24);
90	}
91	
92	static void chacha_init(mi_random_ctx_t* ctx, const uint8_t key[32], uint64_t nonce)
93	{
94	  // since we only use chacha for randomness (and not encryption) we
95	  // do not _need_ to read 32-bit values as little endian but we do anyways
96	  // just for being compatible :-)
97	  ctx->output_available = 0;
98	  _mi_memzero(ctx->output,sizeof(ctx->output));
99	  for (size_t i = 0; i < 4; i++) {
100	    const uint8_t* sigma = (uint8_t*)"expand 32-byte k";
101	    ctx->input[i] = read32(sigma,i);
102	  }
103	  for (size_t i = 0; i < 8; i++) {
104	    ctx->input[i + 4] = read32(key,i);
105	  }
106	  ctx->input[12] = 0;
107	  ctx->input[13] = 0;
108	  ctx->input[14] = (uint32_t)nonce;
109	  ctx->input[15] = (uint32_t)(nonce >> 32);
110	}
111	
112	static void chacha_split(mi_random_ctx_t* ctx, uint64_t nonce, mi_random_ctx_t* ctx_new) {
113	  _mi_memzero(ctx_new, sizeof(*ctx_new));
114	  ctx_new->weak = ctx->weak;
115	  _mi_memcpy(ctx_new->input, ctx->input, sizeof(ctx_new->input));
116	  ctx_new->input[12] = 0;
117	  ctx_new->input[13] = 0;
118	  ctx_new->input[14] = (uint32_t)nonce;
119	  ctx_new->input[15] = (uint32_t)(nonce >> 32);
120	  mi_assert_internal(ctx->input[14] != ctx_new->input[14] || ctx->input[15] != ctx_new->input[15]); // do not reuse nonces!
121	  chacha_block(ctx_new);
122	}
