135	void _mi_random_split(mi_random_ctx_t* ctx, mi_random_ctx_t* ctx_new) {
136	  mi_assert_internal(mi_random_is_initialized(ctx));
137	  mi_assert_internal(ctx != ctx_new);  
138	  const uintptr_t nonce_rnd = _mi_random_next(ctx);
139	  chacha_split(ctx, (uintptr_t)ctx_new ^ nonce_rnd /*nonce*/, ctx_new);
140	}
