147	    r = chacha_next32(ctx);
148	    #elif MI_INTPTR_SIZE == 8
149	    r = (((uintptr_t)chacha_next32(ctx) << 32) | chacha_next32(ctx));
150	    #else
151	    # error "define mi_random_next for this platform"
152	    #endif
153	  } while (r==0);
154	  return r;
155	}
